import { useMemo, useState } from "react";
import { Pressable, ScrollView, StyleSheet, Text, View } from "react-native";
import { spacing, useKeatingTheme } from "@/constants/theme";
import { activityYears, buildActivityCalendar, type ActivityDay } from "@/lib/usage-insights";
import type { SessionStartActivity } from "@/lib/usage-summary";

interface ActivityCalendarProps {
  sessionStarts: SessionStartActivity[];
  onOpenSession: (sessionId: string) => void;
}

export function ActivityCalendar({ sessionStarts, onOpenSession }: ActivityCalendarProps) {
  const theme = useKeatingTheme();
  const styles = createStyles(theme);
  const years = useMemo(() => activityYears(sessionStarts), [sessionStarts]);
  const [requestedYear, setRequestedYear] = useState(() => years[0] ?? new Date().getFullYear());
  const year = years.includes(requestedYear) ? requestedYear : years[0] ?? new Date().getFullYear();
  const calendar = useMemo(() => buildActivityCalendar(year, sessionStarts), [sessionStarts, year]);
  const activeDays = calendar.days.filter((day) => day.count > 0);
  const [selectedKey, setSelectedKey] = useState<string | null>(null);
  const selected = calendar.days.find((day) => day.key === selectedKey && day.count > 0)
    ?? activeDays.at(-1)
    ?? null;
  const cells: Array<ActivityDay | null> = [
    ...Array.from({ length: calendar.leadingEmptyDays }, () => null),
    ...calendar.days,
  ];
  const weeks = Array.from({ length: Math.ceil(cells.length / 7) }, (_, index) => cells.slice(index * 7, index * 7 + 7));

  if (!sessionStarts.length) {
    return <Text style={styles.empty}>Start a lesson to add its first day to this calendar.</Text>;
  }

  return (
    <View>
      <View accessibilityRole="tablist" style={styles.years}>
        {years.map((candidate) => (
          <Pressable
            key={candidate}
            accessibilityRole="tab"
            accessibilityState={{ selected: candidate === year }}
            onPress={() => { setRequestedYear(candidate); setSelectedKey(null); }}
            style={({ pressed }) => [styles.yearButton, candidate === year && styles.yearSelected, pressed && styles.pressed]}
          >
            <Text style={[styles.yearText, candidate === year && styles.yearTextSelected]}>{candidate}</Text>
          </Pressable>
        ))}
      </View>

      <View style={styles.calendarRow}>
        <View style={styles.weekdayLabels} importantForAccessibility="no-hide-descendants">
          {['S', 'M', 'T', 'W', 'T', 'F', 'S'].map((label, index) => <Text key={`${label}-${index}`} style={styles.weekday}>{label}</Text>)}
        </View>
        <ScrollView horizontal showsHorizontalScrollIndicator contentContainerStyle={styles.weeks}>
          {weeks.map((week, weekIndex) => (
            <View key={weekIndex} style={styles.week}>
              {week.map((day, dayIndex) => day ? (
                <Pressable
                  key={day.key}
                  accessibilityRole="button"
                  accessibilityLabel={`${formatDay(day)}, ${day.count} lesson${day.count === 1 ? "" : "s"} started`}
                  accessibilityState={{ selected: selected?.key === day.key }}
                  disabled={day.count === 0}
                  hitSlop={5}
                  onPress={() => setSelectedKey(day.key)}
                  style={styles.cellTarget}
                >
                  <View style={[
                    styles.cell,
                    { backgroundColor: activityColor(theme.colors.surfacePressed, theme.colors.primary, day.count, calendar.maxCount) },
                    selected?.key === day.key && styles.cellSelected,
                  ]} />
                </Pressable>
              ) : <View key={`empty-${dayIndex}`} style={styles.cellTarget} />)}
            </View>
          ))}
        </ScrollView>
      </View>

      {selected ? (
        <View style={styles.selection}>
          <Text style={styles.selectionTitle}>{formatDay(selected)}</Text>
          <Text style={styles.selectionCount}>{selected.count} lesson{selected.count === 1 ? "" : "s"} started</Text>
          {selected.sessions.map((session) => (
            <Pressable
              key={session.id}
              accessibilityRole="button"
              accessibilityLabel={`Open lesson ${session.title}`}
              onPress={() => onOpenSession(session.id)}
              style={({ pressed }) => [styles.session, pressed && styles.pressed]}
            >
              <Text numberOfLines={1} style={styles.sessionTitle}>{session.title}</Text>
              <Text style={styles.sessionMeta}>{session.messages} messages</Text>
            </Pressable>
          ))}
        </View>
      ) : null}
    </View>
  );
}

function formatDay(day: ActivityDay): string {
  return new Intl.DateTimeFormat(undefined, { month: "long", day: "numeric", year: "numeric" })
    .format(new Date(day.year, day.month - 1, day.day));
}

function activityColor(empty: string, active: string, count: number, maxCount: number): string {
  if (!count || !maxCount) return empty;
  return mixHex(empty, active, 0.3 + (count / maxCount) * 0.7);
}

function mixHex(background: string, foreground: string, weight: number): string {
  if (!/^#[0-9a-f]{6}$/i.test(background) || !/^#[0-9a-f]{6}$/i.test(foreground)) return foreground;
  const channels = (value: string) => [1, 3, 5].map((offset) => Number.parseInt(value.slice(offset, offset + 2), 16));
  const base = channels(background);
  const overlay = channels(foreground);
  return `#${base.map((channel, index) => Math.round(channel * (1 - weight) + overlay[index]! * weight).toString(16).padStart(2, "0")).join("")}`;
}

function createStyles(theme: ReturnType<typeof useKeatingTheme>) {
  const { colors, type } = theme;
  return StyleSheet.create({
    empty: { ...type.body, color: colors.textMuted, paddingVertical: spacing.md },
    years: { flexDirection: "row", flexWrap: "wrap", gap: spacing.sm, marginBottom: spacing.sm },
    yearButton: { minHeight: 44, minWidth: 58, alignItems: "center", justifyContent: "center", borderRadius: 10 },
    yearSelected: { backgroundColor: colors.surfacePressed },
    yearText: { ...type.label, color: colors.textMuted },
    yearTextSelected: { color: colors.primaryText },
    calendarRow: { flexDirection: "row" },
    weekdayLabels: { paddingTop: 2 },
    weekday: { ...type.caption, color: colors.textFaint, width: 18, height: 30, lineHeight: 30, textAlign: "center" },
    weeks: { gap: 2, paddingHorizontal: spacing.xs, paddingBottom: spacing.sm },
    week: { gap: 2 },
    cellTarget: { width: 30, height: 30, alignItems: "center", justifyContent: "center" },
    cell: { width: 18, height: 18, borderRadius: 4 },
    cellSelected: { borderWidth: 2, borderColor: colors.text },
    selection: { marginTop: spacing.md, borderTopWidth: 1, borderTopColor: colors.border, paddingTop: spacing.md },
    selectionTitle: { ...type.label, color: colors.text },
    selectionCount: { ...type.caption, color: colors.textMuted, marginTop: 2, marginBottom: spacing.xs },
    session: { minHeight: 44, flexDirection: "row", alignItems: "center", gap: spacing.sm, borderBottomWidth: 1, borderBottomColor: colors.border },
    sessionTitle: { ...type.body, flex: 1, color: colors.text },
    sessionMeta: { ...type.caption, color: colors.textMuted },
    pressed: { opacity: 0.72 },
  });
}

import { useMemo, useState } from "react";
import { Pressable, StyleSheet, Text, View } from "react-native";
import Svg, { Circle } from "react-native-svg";
import { spacing, useKeatingTheme } from "@/constants/theme";
import { buildTopicSlices } from "@/lib/usage-insights";
import type { TopicActivity } from "@/lib/usage-summary";

const SIZE = 168;
const CENTER = SIZE / 2;
const RADIUS = 58;
const CIRCUMFERENCE = Math.PI * 2 * RADIUS;
const PALETTE = ["#22c55e", "#2563eb", "#8b5cf6", "#ec4899", "#f59e0b", "#06b6d4", "#dc2626", "#64748b", "#84cc16"];

export function TopicWheel({ topics }: { topics: TopicActivity[] }) {
  const theme = useKeatingTheme();
  const styles = createStyles(theme);
  const slices = useMemo(() => buildTopicSlices(topics), [topics]);
  const [selectedKey, setSelectedKey] = useState<string | null>(null);
  const selected = slices.find((slice) => slice.key === selectedKey) ?? slices[0] ?? null;
  const total = slices.reduce((sum, slice) => sum + slice.count, 0);
  let offset = 0;

  if (!slices.length) return <Text style={styles.empty}>Record a named lesson or topic-linked artifact to build this view.</Text>;

  return (
    <View>
      <View style={styles.chartRow}>
        <View accessible accessibilityRole="image" accessibilityLabel={`Topic activity wheel with ${slices.length} slices and ${total} recorded evidence items`}>
          <Svg width={SIZE} height={SIZE} viewBox={`0 0 ${SIZE} ${SIZE}`}>
            <Circle cx={CENTER} cy={CENTER} r={RADIUS} fill="none" stroke={theme.colors.surfacePressed} strokeWidth={26} />
            {slices.map((slice, index) => {
              const start = offset;
              const length = slice.share * CIRCUMFERENCE;
              offset += length;
              return (
                <Circle
                  key={slice.key}
                  cx={CENTER}
                  cy={CENTER}
                  r={RADIUS}
                  fill="none"
                  stroke={PALETTE[index % PALETTE.length]}
                  strokeWidth={selected?.key === slice.key ? 30 : 24}
                  strokeDasharray={`${Math.max(0, length - 3)} ${CIRCUMFERENCE}`}
                  strokeDashoffset={-start}
                  strokeLinecap="butt"
                  rotation={-90}
                  origin={`${CENTER}, ${CENTER}`}
                />
              );
            })}
          </Svg>
          <View pointerEvents="none" style={styles.centerLabel}>
            <Text style={styles.centerValue}>{selected?.count ?? total}</Text>
            <Text numberOfLines={2} style={styles.centerCopy}>{selected?.label ?? "evidence"}</Text>
          </View>
        </View>
        <View style={styles.legend}>
          {slices.map((slice, index) => (
            <Pressable
              key={slice.key}
              accessibilityRole="button"
              accessibilityLabel={`${slice.label}, ${slice.count} recorded evidence item${slice.count === 1 ? "" : "s"}`}
              accessibilityState={{ selected: selected?.key === slice.key }}
              onPress={() => setSelectedKey(slice.key)}
              style={({ pressed }) => [styles.legendRow, selected?.key === slice.key && styles.legendSelected, pressed && styles.pressed]}
            >
              <View style={[styles.swatch, { backgroundColor: PALETTE[index % PALETTE.length] }]} />
              <Text numberOfLines={1} style={styles.legendLabel}>{slice.label}</Text>
              <Text style={styles.legendCount}>{Math.round(slice.share * 100)}%</Text>
            </Pressable>
          ))}
        </View>
      </View>
      {selected ? (
        <Text style={styles.detail}>
          {selected.count} recorded evidence item{selected.count === 1 ? "" : "s"} · {selected.turns} messages · {selected.source}
        </Text>
      ) : null}
    </View>
  );
}

function createStyles(theme: ReturnType<typeof useKeatingTheme>) {
  const { colors, type } = theme;
  return StyleSheet.create({
    empty: { ...type.body, color: colors.textMuted, paddingVertical: spacing.md },
    chartRow: { flexDirection: "row", flexWrap: "wrap", alignItems: "center", gap: spacing.md },
    centerLabel: { position: "absolute", inset: 0, alignItems: "center", justifyContent: "center", paddingHorizontal: 42 },
    centerValue: { ...type.heading, ...type.monoBold, color: colors.text },
    centerCopy: { ...type.caption, color: colors.textMuted, textAlign: "center" },
    legend: { flex: 1, minWidth: 170 },
    legendRow: { minHeight: 44, flexDirection: "row", alignItems: "center", gap: spacing.sm, paddingHorizontal: spacing.sm, borderRadius: 10 },
    legendSelected: { backgroundColor: colors.surfacePressed },
    swatch: { width: 12, height: 12, borderRadius: 3 },
    legendLabel: { ...type.caption, flex: 1, color: colors.text },
    legendCount: { ...type.caption, ...type.mono, color: colors.textMuted },
    detail: { ...type.caption, color: colors.textMuted, lineHeight: 19, marginTop: spacing.sm },
    pressed: { opacity: 0.72 },
  });
}

import { File } from "expo-file-system";
import { getProviderKey } from "./storage";
import type { ProviderId } from "./types";

export type TranscriptionProvider = "openai" | "google";

export interface TranscriptionCredential {
  provider: TranscriptionProvider;
  apiKey: string;
}

type KeyReader = (provider: ProviderId) => Promise<string | null>;

export async function resolveTranscriptionCredential(
  activeProvider: ProviderId,
  readKey: KeyReader = getProviderKey,
): Promise<TranscriptionCredential | null> {
  const preferred: TranscriptionProvider[] = activeProvider === "google"
    ? ["google", "openai"]
    : ["openai", "google"];
  for (const provider of preferred) {
    const apiKey = await readKey(provider);
    if (apiKey?.trim()) return { provider, apiKey: apiKey.trim() };
  }
  return null;
}

export async function transcribeAudioUri(
  uri: string,
  mimeType: string,
  activeProvider: ProviderId,
  options: {
    fetchImpl?: typeof fetch;
    readKey?: KeyReader;
    readBase64?: (uri: string) => Promise<string>;
  } = {},
): Promise<string> {
  const credential = await resolveTranscriptionCredential(activeProvider, options.readKey);
  if (!credential) throw new Error("Add an OpenAI or Google API key in Settings to dictate a message.");
  if (credential.provider === "openai") {
    return transcribeOpenAi(uri, mimeType, credential.apiKey, options.fetchImpl ?? fetch);
  }
  const readBase64 = options.readBase64 ?? (async (fileUri: string) => new File(fileUri).base64());
  return transcribeGoogle(await readBase64(uri), mimeType, credential.apiKey, options.fetchImpl ?? fetch);
}

async function transcribeOpenAi(uri: string, mimeType: string, apiKey: string, fetchImpl: typeof fetch): Promise<string> {
  const form = new FormData();
  form.append("file", { uri, name: "keating-dictation.m4a", type: mimeType } as unknown as Blob);
  form.append("model", "gpt-4o-transcribe");
  const response = await fetchImpl("https://api.openai.com/v1/audio/transcriptions", {
    method: "POST",
    headers: { Authorization: `Bearer ${apiKey}` },
    body: form,
  });
  const payload = await readJson(response);
  if (!response.ok) throw new Error(transcriptionError(payload, response.status));
  const text = typeof payload.text === "string" ? payload.text.trim() : "";
  if (!text) throw new Error("The transcription service returned no speech.");
  return text;
}

async function transcribeGoogle(audio: string, mimeType: string, apiKey: string, fetchImpl: typeof fetch): Promise<string> {
  const response = await fetchImpl(
    `https://generativelanguage.googleapis.com/v1beta/models/gemini-2.5-flash:generateContent?key=${encodeURIComponent(apiKey)}`,
    {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({
        contents: [{ role: "user", parts: [
          { text: "Transcribe this audio verbatim. Return only the transcript text, with no commentary." },
          { inlineData: { mimeType, data: audio } },
        ] }],
      }),
    },
  );
  const payload = await readJson(response);
  if (!response.ok) throw new Error(transcriptionError(payload, response.status));
  const text = Array.isArray(payload.candidates?.[0]?.content?.parts)
    ? payload.candidates[0].content.parts.map((part: unknown) =>
      typeof part === "object" && part !== null && typeof (part as { text?: unknown }).text === "string"
        ? (part as { text: string }).text
        : "").join("").trim()
    : "";
  if (!text) throw new Error("The transcription service returned no speech.");
  return text;
}

async function readJson(response: Response): Promise<Record<string, any>> {
  const text = await response.text();
  try {
    return text ? JSON.parse(text) : {};
  } catch {
    return { error: { message: text.slice(0, 500) } };
  }
}

function transcriptionError(payload: Record<string, any>, status: number): string {
  const message = payload.error?.message ?? payload.message;
  return `Transcription failed (${status}): ${typeof message === "string" && message.trim() ? message.slice(0, 500) : "provider request failed"}`;
}

