  spacer: { height: spacing.sm },
  listRow: { flexDirection: "row", alignItems: "flex-start", gap: spacing.sm, paddingLeft: spacing.xs },
  bullet: { ...type.body, color: colors.primaryText, width: 12 },
  number: { ...type.body, ...type.mono, color: colors.primaryText, minWidth: 24 },
