						ref={expandButtonRef}
						type="button"
						className={expandButtonClass}
						aria-label="Expand diagram"
						aria-expanded={expanded}
						title="Expand diagram"
						onClick={() => setExpanded(true)}
					>
						<Maximize2 aria-hidden="true" size={16} />
					</button>
					{expanded && typeof document !== "undefined"
						? createPortal(
								<div
									className={expandedBackdropClass}
									onMouseDown={(event) => {
										if (event.target === event.currentTarget) setExpanded(false);
									}}
								>
									<section
										className={expandedPanelClass}
										role="dialog"
										aria-modal="true"
										aria-label="Expanded Mermaid diagram"
									>
										<header className={expandedToolbarClass}>
											<h2 className={expandedTitleClass}>Expanded diagram</h2>
											<button
												ref={closeButtonRef}
												type="button"
												className={closeButtonClass}
												aria-label="Close expanded diagram"
												title="Close expanded diagram"
												onClick={() => setExpanded(false)}
											>
												<X aria-hidden="true" size={18} />
											</button>
										</header>
										<div className={expandedViewportClass}>
											<div className={expandedDiagramClass} dangerouslySetInnerHTML={{…8486 tokens truncated…e code", choiceLabel: "Meaning" }',
	'], "ephemeral", "DNS diagnosis", "Answer each prompt in its intended format.")',
].join("\n");

