    // thinking budget, so the reasoning control never offers an unsupported
    // parameter. A miss just leaves the built-in catalog in place.
    readCachedModelCatalog()
      .then((cached) => {
        if (!cancelled && cached.length > 0) setCatalog(mergeCatalogModels(BUILT_IN_MODEL_CATALOG, cached));
      })
      .catch(() => undefined);

    loadPersona()
      .then((storedPersona) => {
        if (cancelled) return;
        personaRef.current = storedPersona;
        setPersonaState(storedPersona);
      })
      .catch((error) => {
        if (!cancelled) setStorageError(error instanceof Error ? error.message : "Could not load the tutor persona.");
      });

    bootstrapLearnerRepository()
      .then(async ({ repository }) => {
        openedRepository = repository;
        if (cancelled) {
          void repository.close();
          return;
        }
        // Repository bootstrap owns migration and interrupted-delete recovery,
        // so the legacy UI cache is read only after those operations settle.
        const persisted = await loadPersistedState();
        const snapshot = await repository.records.snapshot();
        const localAttachments = await repository.records.getLocalAttachments();
        const projected = projectPortableToNativeState(
          snapshot,
          persisted?.providerSettings ?? DEFAULT_PROVIDER_SETTINGS,
          localAttachments,
          persisted?.activeSessionId,
        );
        const next = normalizeState(projected.state);
        const storedLearnerContext = await loadLearnerContext();
        if (cancelled) {
          void repository.close();
          return;
        }
        learnerRepositoryRef.current = repository;
        stateRef.current = next;
        setState(next);
        setLearnerData(snapshot);
        learnerContextRef.current = storedLearnerContext;
        setLearnerContextState(storedLearnerContext);
        setPersistenceReady(true);
        setRepositoryReady(true);
      })
      .catch(async (error) => {
        if (!cancelled) {
          setStorageError(error instanceof Error
            ? `SQLite learner repository: ${error.message}`
            : "Could not open the SQLite learner repository.");
          // Keep the learner's preserved cache usable when SQLite cannot open;
          // no repository-backed feature is claimed in this recovery mode.
          try {
            const next = normalizeState(await loadPersistedState());
            stateRef.current = next;
            setState(next);
            setPersistenceReady(true);
          } catch {
            // The primary error already explains why storage is unavailable.
          }
        }
      })
      .finally(() => {
        if (!cancelled) setHydrated(true);
      });
    return () => {
      cancelled = true;
      const repository = learnerRepositoryRef.current ?? openedRepository;
      learnerRepositoryRef.current = null;
      if (repository) {
        void learnerRepositoryWriteTailRef.current
          .catch(() => undefined)
          .then(() => repository.close());
      }
    };
  }, []);

  const persistLearnerState = useCallback(async (next: PersistedAppState) => {
    const repository = learnerRepositoryRef.current;
    if (!repository || learnerRepositoryClearingRef.current) return;
    const write = learnerRepositoryWriteTailRef.current
      .catch(() => undefined)
      .then(async () => {
        if (learnerRepositoryClearingRef.current) return;
        const current = await repository.records.snapshot();
        const currentLocations = await repository.records.getLocalAttachments();
        const reconciled = reconcileNativeStateIntoPortable(current, next, currentLocations);
        await repository.records.replaceWithLocalAttachments(reconciled.data, reconciled.localAttachments);
        setLearnerData(reconciled.data);
      });
    learnerRepositoryWriteTailRef.current = write;
    await write;
  }, []);

  const mutateLearnerRecords = useCallback(async <Result,>(
    mutation: (current: PortableLearnerData, now: string) => { data: PortableLearnerData; result: Result },
  ): Promise<Result> => {
    const repository = learnerRepositoryRef.current;
    if (!repository || learnerRepositoryClearingRef.current) {
      throw new Error("Learning data is still loading. Wait a moment and try again.");
    }
    let result: Result | undefined;
    const write = learnerRepositoryWriteTailRef.current
      .catch(() => undefined)
      .then(async () => {
        if (learnerRepositoryClearingRef.current) throw new Error("Learning data is being cleared. Try again when it finishes.");
        const updated = await repository.records.mutatePortable((current, now) => {
          const applied = mutation(current, now);
          result = applied.result;
          return applied.data;
        });
        setLearnerData(updated);
      });
    learnerRepositoryWriteTailRef.current = write;
    try {
      await write;
    } catch (error) {
      setStorageError(error instanceof Error ? error.message : "Could not update the learner repository.");
      throw error;
    }
    if (result === undefined) throw new Error("The learner update did not produce a result.");
    return result;
  }, []);

  const queueLearnerState = useCallback((next: PersistedAppState) => {
    void persistLearnerState(next).catch((error) => {
      setStorageError(error instanceof Error ? error.message : "Could not save the SQLite learner repository.");
    });
  }, [persistLearnerState]);

  useEffect(() => {
    if (!hydrated || !persistenceReady) return;
    const timeout = setTimeout(() => {
      savePersistedState(state).catch((error) => {
        setStorageError(error instanceof Error ? error.message : "Could not save local learning data.");
      });
    }, 120);
    return () => clearTimeout(timeout);
  }, [hydrated, persistenceReady, state]);

  useEffect(() => {
    if (!hydrated || !repositoryReady) return;
    const timeout = setTimeout(() => {
      const repository = learnerRepositoryRef.current;
      if (!repository) return;
      try {
        persistLearnerState(state).catch((error) => {
            setStorageError(error instanceof Error ? error.message : "Could not save the SQLite learner repository.");
        });
      } catch (error) {
        setStorageError(error instanceof Error ? error.message : "Could not prepare learning data for SQLite.");
      }
    }, 120);
    return () => clearTimeout(timeout);
  }, [hydrated, persistLearnerState, repositoryReady, state]);

  const activeSession = useMemo(
    () => state.sessions.find((session) => session.id === state.activeSessionId) ?? state.sessions[0],
    [state.activeSessionId, state.sessions],
  );

  const updateSession = useCallback((sessionId: string, update: (session: ChatSession) => ChatSession) => {
    const current = stateRef.current;
    const next = {
      ...current,
      sessions: current.sessions.map((session) => session.id === sessionId ? update(session) : session),
    };
    stateRef.current = next;
    setState(next);
    return next;
  }, []);

  const runCompletion = useCallback(async (sessionId: string, messages: ChatMessage[]) => {
    const snapshot = stateRef.current;
    const settings = snapshot.providerSettings;
    const definition = providerDefinition(settings.provider);
    const controller = new AbortController();
    abortControllerRef.current = controller;
    generationBusyRef.current = true;
    setIsGenerating(true);
    setRawGenerationError(null);

    const finishBeforeStream = () => {
      if (abortControllerRef.current === controller) abortControllerRef.current = null;
      generationBusyRef.current = false;
      setIsGenerating(false);
    };

    let apiKey: string | null;
    try {
      apiKey = await getProviderKey(settings.provider);
    } catch (error) {
      finishBeforeStream();
      setRawGenerationError(error instanceof Error ? error.message : "Could not read the provider credential.");
      return;
    }
    if (controller.signal.aborted) {
      finishBeforeStream();
      return;
    }
    if (definition.requiresKey && !apiKey) {
      finishBeforeStream();
      setRawGenerationError(`Add your ${definition.label} API key in Settings before sending a message.`);
      return;
    }

    // The placeholder is appended immediately so streamed tokens land in a
    // message the chat list is already rendering.
    const assistantId = createId("message");
    const startedAt = Date.now();
    updateSession(sessionId, (session) => ({
      ...session,
      messages: [...messages, { id: assistantId, role: "assistant", content: "", createdAt: startedAt }],
      updatedAt: startedAt,
    }));
    setStreamingMessageId(assistantId);

    const writeContent = (content: string, usage?: ProviderUsage) =>
      updateSession(sessionId, (session) => ({
        ...session,
        messages:…8475 tokens truncated… commonHeaders,
        signal,
        body: JSON.stringify({
          systemInstruction: { parts: [{ text: systemPrompt }] },
          contents: history.map((message) => ({
            role: message.role === "assistant" ? "model" : "user",
            parts: geminiMessageParts(message),
          })),
          generationConfig: {
            temperature: settings.temperature,
            maxOutputTokens: 4096,
            ...(googleBudget === null ? {} : { thinkingConfig: { thinkingBudget: googleBudget } }),
          },
        }),
      },
    };
  }

  const chatEffort = settings.provider === "openrouter"
    ? openRouterReasoningEffort(reasoningLevel)
    : openAiReasoningEffort(reasoningLevel);
  if (apiKey) commonHeaders.Authorization = `Bearer ${apiKey}`;
  if (settings.provider === "openrouter") {
    commonHeaders["HTTP-Referer"] = "https://keating.help";
    commonHeaders["X-Title"] = "Keating Mobile";
  }

  return {
    url: openAiChatUrl(settings.baseUrl),
    init: {
      method: "POST",
      headers: commonHeaders,
      signal,
      body: JSON.stringify({
        model: settings.model,
        ...(supportsTemperature ? { temperature: settings.temperature } : {}),
        ...(chatEffort
          ? settings.provider === "openrouter"
            ? { reasoning: { effort: chatEffort } }
            : { reasoning_effort: chatEffort }
          : {}),
        ...(stream ? { stream: true } : {}),
        messages: [
          { role: "system", content: systemPrompt },
          ...history.map((message) => ({
            role: message.role,
            content: chatMessageContent(message, settings.provider === "openrouter"),
          })),
        ],
      }),
    },
  };
}

function providerErrorMessage(payload: unknown, fallback: string): string {
  if (typeof payload !== "object" || payload === null) return fallback;
  const record = payload as Record<string, unknown>;
  const error = record.error;
  if (typeof error === "string" && error.trim()) return error;
  if (typeof error === "object" && error !== null) {
    const message = (error as Record<string, unknown>).message;
    if (typeof message === "string" && message.trim()) return message;
  }
  const message = record.message;
  return typeof message === "string" && message.trim() ? message : fallback;
}

function boundedProviderText(value: string): string {
  const compact = value.replace(/\s+/g, " ").trim();
  return compact.length > 2_000 ? `${compact.slice(0, 1_999)}…` : compact;
}

function extractProviderText(settings: ProviderSettings, payload: unknown): string {
  const record = payload as Record<string, any>;
  if (settings.provider === "openai") {
    if (typeof record.output_text === "string" && record.output_text.trim()) return record.output_text.trim();
    const text = Array.isArray(record.output)
      ? record.output
        .flatMap((item: any) => Array.isArray(item?.content) ? item.content : [])
        .filter((part: any) => part?.type === "output_text" && typeof part?.text === "string")
        .map((part: any) => part.text)
        .join("\n")
      : "";
    if (text.trim()) return text.trim();
  } else if (settings.provider === "anthropic") {
    const text = Array.isArray(record.content)
      ? record.content.filter((block: any) => block?.type === "text").map((block: any) => block.text).join("\n")
      : "";
    if (text.trim()) return text.trim();
  } else if (settings.provider === "google") {
    const text = record.candidates?.[0]?.content?.parts
      ?.filter((part: any) => part?.thought !== true)
      .map((part: any) => typeof part?.text === "string" ? part.text : "")
      .join("\n");
    if (typeof text === "string" && text.trim()) return text.trim();
  } else {
    const content = record.choices?.[0]?.message?.content;
    if (typeof content === "string" && content.trim()) return content.trim();
    if (Array.isArray(content)) {
      const text = content.map((part: any) => part?.text ?? "").join("\n");
      if (text.trim()) return text.trim();
    }
  }
  throw new Error("The provider returned a response without readable text.");
}

function finiteCount(value: unknown): number | undefined {
  return typeof value === "number" && Number.isFinite(value) && value >= 0 ? value : undefined;
}

export function extractProviderUsage(settings: ProviderSettings, payload: unknown): ProviderUsage | null {
  if (typeof payload !== "object" || payload === null) return null;
  const record = payload as Record<string, any>;
  let usage: Record<string, unknown> | undefined;
  if (settings.provider === "openai") usage = record.response?.usage ?? record.usage;
  else if (settings.provider === "anthropic") usage = record.message?.usage ?? record.usage;
  else if (settings.provider === "google") usage = record.usageMetadata;
  else usage = record.usage;
  if (!usage || typeof usage !== "object") return null;

  const inputTokens = finiteCount(usage.input_tokens ?? usage.prompt_tokens ?? usage.promptTokenCount) ?? 0;
  const outputTokens = finiteCount(usage.output_tokens ?? usage.completion_tokens ?? usage.candidatesTokenCount) ?? 0;
  const totalTokens = finiteCount(usage.total_tokens ?? usage.totalTokenCount) ?? inputTokens + outputTokens;
  const costUsd = finiteCount(usage.cost ?? usage.cost_usd);
  if (inputTokens === 0 && outputTokens === 0 && totalTokens === 0 && costUsd === undefined) return null;
  return { inputTokens, outputTokens, totalTokens, ...(costUsd === undefined ? {} : { costUsd }) };
}

function mergeProviderUsage(current: ProviderUsage | null, next: ProviderUsage | null): ProviderUsage | null {
  if (!next) return current;
  if (!current) return next;
  const inputTokens = Math.max(current.inputTokens, next.inputTokens);
  const outputTokens = Math.max(current.outputTokens, next.outputTokens);
  return {
    inputTokens,
    outputTokens,
    totalTokens: Math.max(current.totalTokens, next.totalTokens, inputTokens + outputTokens),
    ...(current.costUsd === undefined && next.costUsd === undefined
      ? {}
      : { costUsd: Math.max(current.costUsd ?? 0, next.costUsd ?? 0) }),
  };
}

const EVENT_SEPARATOR = /\r?\n\r?\n/;

/**
 * Splits an incoming SSE text stream into `data:` payload strings, carrying any
 * partial trailing event across chunk boundaries.
 */
export function createSseParser(): (chunk: string) => string[] {
  let buffer = "";
  return (chunk: string) => {
    buffer += chunk;
    const events: string[] = [];
    for (let match = EVENT_SEPARATOR.exec(buffer); match; match = EVENT_SEPARATOR.exec(buffer)) {
      const rawEvent = buffer.slice(0, match.index);
      buffer = buffer.slice(match.index + match[0].length);
      const data = rawEvent
        .split(/\r?\n/)
        .filter((line) => line.startsWith("data:"))
        .map((line) => line.slice(5).trim())
        .join("\n");
      if (data) events.push(data);
    }
    return events;
  };
}

function textFromParts(parts: unknown): string {
  if (typeof parts === "string") return parts;
  if (!Array.isArray(parts)) return "";
  // Gemini returns its thinking as ordinary parts flagged `thought: true`.
  // Those belong to the reasoning budget, not the reply the learner reads.
  return parts
    .filter((part: any) => part?.thought !== true)
    .map((part: any) => (typeof part?.text === "string" ? part.text : ""))
    .join("");
}

/**
 * Pulls the incremental text out of one SSE event for the given provider.
 * Returns an empty string for keep-alives and non-text events.
 */
export function extractStreamDelta(settings: ProviderSettings, data: string): string {
  if (!data || data === "[DONE]") return "";
  let payload: any;
  try {
    payload = JSON.parse(data);
  } catch {
    return "";
  }

  if (payload?.error) {
    throw new Error(providerErrorMessage(payload, "The provider reported a streaming error."));
  }

  if (settings.provider === "anthropic") {
    if (payload.type === "content_block_delta" && payload.delta?.type === "text_delta") {
      return typeof payload.delta.text === "string" ? payload.delta.text : "";
    }
    return "";
  }

  if (settings.provider === "openai") {
    if (payload.type === "response.failed") {
      const nested = payload.response?.error ?? payload.response;
      throw new Error(providerErrorMessage({ error: nested }, "The OpenAI response failed."));
    }
    return payload.type === "response.output_text.delta" && typeof payload.delta === "string" ? payload.delta : "";
  }

  if (settings.provider === "google") {
    return textFromParts(payload?.candidates?.[0]?.content?.parts);
  }

  const delta = payload?.choices?.[0]?.delta;
  if (typeof delta?.content === "string") return delta.content;
  return textFromParts(delta?.content);
}

async function throwProviderError(response: Response): Promise<never> {
  const text = await response.text().catch(() => "");
  let payload: unknown = {};
  try {
    payload = text ? JSON.parse(text) : {};
  } catch {
    const plainText = boundedProviderText(text);
    throw new Error(plainText || `Provider request failed with HTTP ${response.status}.`);
  }
  throw new Error(providerErrorMessage(payload, `Provider request failed with HTTP ${response.status}.`));
}

export interface StreamCompletionOptions extends ProviderRequestOptions {
  /** Called with each incremental text chunk as it arrives. */
  onDelta?: (delta: string, accumulated: string) => void;
  onUsage?: (usage: ProviderUsage) => void;
  fetchImpl?: FetchLike;
}

/**
 * Streams a completion, invoking `onDelta` per chunk and resolving with the
 * full text. Falls back to a single non-streamed read when the provider
 * responds without a readable body.
 */
export async function streamCompletion(
  settings: ProviderSettings,
  apiKey: string | null,
  messages: ChatMessage[],
  options: StreamCompletionOptions = {},
): Promise<string> {
  const { onDelta, onUsage, fetchImpl = fetch, ...requestOptions } = options;
  const request = buildProviderRequest(settings, apiKey, messages, { ...requestOptions, stream: true });
  const response = await fetchImpl(request.url, request.init);

  if (!response.ok) await throwProviderError(response);

  const body = response.body;
  if (!body) {
    // No readable stream on this platform — take the whole payload at once.
    return wholePayloadFallback(settings, await response.text(), onDelta, onUsage);
  }

  const decoder = new TextDecoder();
  const parse = createSseParser();
  const reader = body.getReader();
  let accumulated = "";
  let raw = "";
  let usage: ProviderUsage | null = null;

  try {
    while (true) {
      const { done, value } = await reader.read();
      if (done) break;
      const chunk = decoder.decode(value, { stream: true });
      raw += chunk;
      for (const data of parse(chunk)) {
        try {
          usage = mergeProviderUsage(usage, extractProviderUsage(settings, JSON.parse(data)));
        } catch {
          // Keep-alives and non-JSON terminal frames carry no usage.
        }
        const delta = extractStreamDelta(settings, data);
        if (!delta) continue;
        accumulated += delta;
        onDelta?.(delta, accumulated);
      }
    }
  } finally {
    reader.releaseLock();
  }

  const trimmed = accumulated.trim();
  if (trimmed) {
    if (usage) onUsage?.(usage);
    return trimmed;
  }

  // Some OpenAI-compatible servers (local runtimes especially) ignore
  // `stream: true` and answer with one plain JSON body instead of SSE.
  return wholePayloadFallback(settings, raw, onDelta, onUsage);
}

function wholePayloadFallback(
  settings: ProviderSettings,
  text: string,
  onDelta?: (delta: string, accumulated: string) => void,
  onUsage?: (usage: ProviderUsage) => void,
): string {
  let payload: unknown;
  try {
    payload = text.trim() ? JSON.parse(text) : {};
  } catch {
    throw new Error("The provider returned a response without readable text.");
  }
  const content = extractProviderText(settings, payload);
  const usage = extractProviderUsage(settings, payload);
  if (usage) onUsage?.(usage);
  onDelta?.(content, content);
  return content;
}

export async function requestCompletion(
  settings: ProviderSettings,
  apiKey: string | null,
  messages: ChatMessage[],
  signal?: AbortSignal,
  fetchImpl: FetchLike = fetch,
  systemPrompt?: string,
): Promise<string> {
  const request = buildProviderRequest(settings, apiKey, messages, { signal, systemPrompt });
  const response = await fetchImpl(request.url, request.init);
  const responseText = await response.text();
  let payload: unknown = {};
  try {
    payload = responseText ? JSON.parse(responseText) : {};
  } catch {
    if (!response.ok) {
      const plainText = boundedProviderText(responseText);
      throw new Error(plainText || `Provider request failed with HTTP ${response.status}.`);
    }
    throw new Error("The provider returned an invalid JSON response.");
  }

  if (!response.ok) {
    throw new Error(providerErrorMessage(payload, `Provider request failed with HTTP ${response.status}.`));
  }
  return extractProviderText(settings, payload);
}
